<?php
require_once __DIR__.'/db.php'; require_once __DIR__.'/../includes/auth.php'; requireEmployee(); header('Content-Type: application/json; charset=UTF-8');
$method=$_SERVER['REQUEST_METHOD']; if($method==='GET'){ $q=trim($_GET['q']??''); if($q!==''){ $like="%$q%"; $st=$conn->prepare("SELECT s.*,p.name program_name,u.email FROM students s LEFT JOIN programs p ON p.id=s.program_id LEFT JOIN users u ON u.id=s.user_id WHERE s.name LIKE ? OR s.phone LIKE ? ORDER BY s.id DESC");$st->bind_param('ss',$like,$like);$st->execute();$r=$st->get_result(); } else $r=$conn->query("SELECT s.*,p.name program_name,u.email FROM students s LEFT JOIN programs p ON p.id=s.program_id LEFT JOIN users u ON u.id=s.user_id ORDER BY s.id DESC");$rows=[];while($x=$r->fetch_assoc())$rows[]=$x;echo json_encode(['success'=>true,'students'=>$rows],JSON_UNESCAPED_UNICODE);exit; }
if($method==='DELETE'){ $id=(int)($_GET['id']??0);$st=$conn->prepare('DELETE FROM students WHERE id=?');$st->bind_param('i',$id);$st->execute();echo json_encode(['success'=>true,'message'=>'تم الحذف'],JSON_UNESCAPED_UNICODE);exit;}
http_response_code(405);echo json_encode(['success'=>false,'message'=>'Method not allowed'],JSON_UNESCAPED_UNICODE);?>